import{_ as s,o as i,c as o,a0 as t}from"./chunks/framework.Cp0xpwNH.js";const u=JSON.parse('{"title":"Lesson Integration Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"LESSON_INTEGRATION_WORKFLOW.md","filePath":"LESSON_INTEGRATION_WORKFLOW.md"}'),a={name:"LESSON_INTEGRATION_WORKFLOW.md"};function n(d,e,r,l,c,h){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="lesson-integration-workflow" tabindex="-1">Lesson Integration Workflow <a class="header-anchor" href="#lesson-integration-workflow" aria-label="Permalink to &quot;Lesson Integration Workflow&quot;">​</a></h1><p>This document describes how to use the automated lesson integration workflow to add new lessons to the Dutch B1 Curriculum.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The lesson integration workflow is a <strong>single-command automation</strong> that handles everything that must happen after a lesson&#39;s content has been written:</p><ol><li>Locate the lesson file and validate all 20 LESSON_STANDARD.md sections are present</li><li>Archive the research response (if provided)</li><li>Update <code>docs/CURRICULUM.md</code> (mark lesson Complete)</li><li>Update <code>CHANGELOG.md</code> with a detailed entry</li><li>Copy the lesson into <code>docs/[Level]/...</code> (VitePress source root)</li><li>Add the lesson to <code>docs/.vitepress/config.mjs</code> sidebar (skipped if already present)</li><li>Add the lesson to <code>docs/[Level]/index.md</code> landing page (skipped if already present)</li><li>Publish the site (<code>npm run docs:publish</code> -- build + sync into <code>docs/</code>)</li><li><strong>Verify</strong> the resulting HTML file actually exists in <code>docs/</code> before committing anything</li><li>Commit and push to <code>master</code></li><li>Display the next pending lesson</li></ol><p><strong>No manual git commands. No manual VitePress config edits. No manual copying. No forgotten publish step.</strong></p><h2 id="division-of-responsibility" tabindex="-1">Division of Responsibility <a class="header-anchor" href="#division-of-responsibility" aria-label="Permalink to &quot;Division of Responsibility&quot;">​</a></h2><ul><li><strong>You/the AI author</strong> write the lesson&#39;s 20-section content file at its canonical location: <code>[CEFR Level]/Competency-[N]-[Name]/[Lesson ID].md</code> (per <code>docs/LESSON_STANDARD.md</code>). This is a content-authoring task that requires judgment and cannot be scripted.</li><li><strong>The script</strong> (<code>scripts/integrate-lesson.js</code>) handles every mechanical step after that: syncing to <code>docs/</code>, updating the sidebar and landing page, publishing, verifying, and committing/pushing. These steps are deterministic, so they are never done by hand and never skipped.</li></ul><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="command-syntax" tabindex="-1">Command Syntax <a class="header-anchor" href="#command-syntax" aria-label="Permalink to &quot;Command Syntax&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lesson:integrate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lesson-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [research-response-file]</span></span></code></pre></div><p>The research response file is optional -- pass it only if you have not already archived the research output for this lesson under <code>shared/prompts/</code>.</p><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lesson:integrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> A0-06</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./research-output.md</span></span></code></pre></div><p>Or without a research file, if it&#39;s already archived:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lesson:integrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> A0-06</span></span></code></pre></div><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Before running the script, only one thing must exist:</p><ul><li><strong>The lesson file</strong>, at <code>[CEFR Level]/Competency-[N]-[Name]/[Lesson ID].md</code>, with all 20 sections from <code>docs/LESSON_STANDARD.md</code> in order (<code>## 1. Lesson Goal</code> through <code>## 20. Quality Checklist</code>).</li></ul><p>Everything else (copying to <code>docs/</code>, sidebar, landing page, publish, commit, push) is handled by the script.</p><h3 id="what-happens-step-by-step" tabindex="-1">What Happens, Step by Step <a class="header-anchor" href="#what-happens-step-by-step" aria-label="Permalink to &quot;What Happens, Step by Step&quot;">​</a></h3><ol><li><strong>Locate + validate.</strong> Searches <code>A0/</code>, <code>A1/</code>, <code>A2/</code>, <code>B1/</code> for <code>[Lesson ID].md</code> and checks every required <code>## N. Title</code> heading is present. Aborts with a clear error if the file is missing or incomplete -- nothing else runs.</li><li><strong>Archive research response</strong> (only if a file was passed) to <code>shared/prompts/[Lesson ID]-research-response.md</code>.</li><li><strong>Update <code>docs/CURRICULUM.md</code></strong> -- marks the lesson row Complete. Skipped if already Complete.</li><li><strong>Update <code>CHANGELOG.md</code></strong> -- adds an entry under <code>### Added</code>. Skipped if an entry already mentions this lesson file.</li><li><strong>Copy into <code>docs/</code></strong> -- mirrors <code>[Level]/Competency-.../[Lesson ID].md</code> into <code>docs/[Level]/Competency-.../[Lesson ID].md</code> (VitePress&#39;s source root).</li><li><strong>Sidebar</strong> -- checks <code>docs/.vitepress/config.mjs</code> for a link to this lesson; inserts a new competency block if missing.</li><li><strong>Landing page</strong> -- checks <code>docs/[Level]/index.md</code> for a link to this lesson; inserts a new <code>### Competency N: Name</code> section if missing.</li><li><strong>Publish</strong> -- runs <code>npm run docs:publish</code> (<code>vitepress build docs</code> then <code>scripts/publish-docs.js</code>, which syncs the build into <code>docs/</code>). This is the folder GitHub Pages serves (Branch: <code>master</code>, Folder: <code>/docs</code>). <code>docs:build</code> alone is never used here because it only writes to <code>docs/.vitepress/dist/</code>, which is not served.</li><li><strong>Verify</strong> -- confirms <code>docs/[Level]/Competency-.../[Lesson ID].html</code> actually exists on disk. If the build didn&#39;t produce it, the script stops here with an error and does <strong>not</strong> commit, so a broken/incomplete state never gets pushed.</li><li><strong>Commit and push</strong> -- <code>git add -A</code>, commit as <code>Add [Lesson ID]: [Competency Name]</code>, push to <code>master</code>.</li><li><strong>Next lesson</strong> -- reads the first <code>Pending</code> row from <code>docs/CURRICULUM.md</code> and prints it.</li></ol><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="could-not-find-lesson-id-md" tabindex="-1">&quot;Could not find [Lesson ID].md&quot; <a class="header-anchor" href="#could-not-find-lesson-id-md" aria-label="Permalink to &quot;&quot;Could not find [Lesson ID].md&quot;&quot;">​</a></h3><p>The lesson content file hasn&#39;t been written yet, or isn&#39;t at the expected path (<code>[Level]/Competency-[N]-[Name]/[Lesson ID].md</code>). Write it first per <code>docs/LESSON_STANDARD.md</code>.</p><h3 id="is-missing-required-sections-or-out-of-order" tabindex="-1">&quot;is missing required sections (or out of order)&quot; <a class="header-anchor" href="#is-missing-required-sections-or-out-of-order" aria-label="Permalink to &quot;&quot;is missing required sections (or out of order)&quot;&quot;">​</a></h3><p>One or more of the 20 <code>## N. Title</code> headings is missing, misnumbered, or misspelled. Compare against <code>docs/LESSON_STANDARD.md</code> and the list in the script&#39;s <code>REQUIRED_SECTIONS</code>.</p><h3 id="docs-publish-failed" tabindex="-1">&quot;docs:publish failed&quot; <a class="header-anchor" href="#docs-publish-failed" aria-label="Permalink to &quot;&quot;docs:publish failed&quot;&quot;">​</a></h3><p>The VitePress build itself failed. Common causes:</p><ul><li>Unclosed markdown tables</li><li>Heading levels other than <code>##</code> used for section titles</li><li>Broken links to <code>/shared/</code> files that don&#39;t exist</li></ul><p>Fix the lesson file and rerun the script.</p><h3 id="expected-was-not-created-by-the-build" tabindex="-1">&quot;Expected ... was not created by the build&quot; <a class="header-anchor" href="#expected-was-not-created-by-the-build" aria-label="Permalink to &quot;&quot;Expected ... was not created by the build&quot;&quot;">​</a></h3><p>The build succeeded but didn&#39;t produce the expected HTML file -- usually means the lesson wasn&#39;t placed in the folder the script expected, or the sidebar link path doesn&#39;t match the file location. Nothing was committed; safe to fix and rerun.</p><h3 id="git-push-failed" tabindex="-1">Git push failed <a class="header-anchor" href="#git-push-failed" aria-label="Permalink to &quot;Git push failed&quot;">​</a></h3><p>Resolve the underlying git issue (auth, conflicts, network) and push manually:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span></code></pre></div><p>Everything else (lesson file, docs/ copy, CURRICULUM.md, CHANGELOG.md) is already correct locally even if the push itself failed.</p><hr><h2 id="what-not-to-do" tabindex="-1">What NOT to Do <a class="header-anchor" href="#what-not-to-do" aria-label="Permalink to &quot;What NOT to Do&quot;">​</a></h2><ul><li>Don&#39;t run <code>npm run docs:build</code> alone expecting the site to update -- it only writes to <code>docs/.vitepress/dist/</code>, which is not served. Use <code>npm run docs:publish</code> or, better, let <code>npm run lesson:integrate</code> handle it.</li><li>Don&#39;t manually edit generated HTML under <code>docs/*.html</code> or <code>docs/assets/</code> -- it is overwritten every publish.</li><li>Don&#39;t hand-edit <code>docs/.vitepress/dist/</code> -- it&#39;s a build cache, not committed, not served.</li><li>Don&#39;t create multiple lessons in parallel -- process one lesson at a time, in strict curricular order, per <code>docs/CURRICULUM.md</code>.</li></ul><hr><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><p>For issues or questions:</p><ol><li>Check this document (you&#39;re reading it!)</li><li>Check <code>docs/RESEARCH_GUIDELINES.md</code> (research standards)</li><li>Check <code>docs/LESSON_STANDARD.md</code> (lesson structure requirements)</li><li>Check <code>AGENTS.md</code> (workflow overview)</li><li>Check the <code>dutch-lesson-integration</code> skill definition for the full end-to-end process</li></ol><hr><p><em>Last updated: 2026-07-15</em></p>',47)])])}const m=s(a,[["render",n]]);export{u as __pageData,m as default};
